frappe.query_reports["Monthly Group Report - Insurance"] = {
	filters: [
		//{
		//	fieldname: "employee",
		//	label: __("Employee"),
		//	fieldtype: "Link",
		//	options: "Employee"
		//},
		//{
		//	fieldname: "membership_no",
		//	label: __("Membership No."),
		//	fieldtype: "Link",
		//	options: "Insurance Member"
		//},
		//{
		//	fieldname: "insurance_period",
		//	label: __("Insurance Period"),
		//	fieldtype: "Link",
		//	options: "Insurance Period"
		//},
		//{
		//	fieldname: "claim_type",
		//	label: __("Form Type"),
		//	fieldtype: "Link",
		//	options: "Insurance Form"
		//},
		//{
		//	fieldname: "category",
		//	label: __("Category"),
		//	fieldtype: "Link",
		//	options: "Covers and Benefits"
		//},
		//{
		//	fieldname: "claim_status",
		//	label: __("Claim Status"),
		//	fieldtype: "Select",
		//	options: ["","Accepted by Manager","Sent to Doctor","Approved","Rejected"],
		//	default: "Accepted by Manager"
		//},
		{
			fieldname: "group_month",
			label: __("Group Month"),
			fieldtype: "Link",
			options: "Claim Summary"
		}//,
		//{
		//	fieldname: "checked_by_officer",
		//	label: __("Officer Decision"),
		//	fieldtype: "Select",
		//	options: ["", "Accepted", "Declined"]
		//},
		//{
		//	fieldname: "checked_by_manager",
		//	label: __("Manager Decision"),
		//	fieldtype: "Select",
		//	options: ["", "Accepted", "Declined"]
		//}
	],

	formatter: function (value, row, column, data, default_formatter) {
		value = default_formatter(value, row, column, data, default_formatter);
		if (!data) return value;

		// indent 0 — Employee row: bold + light blue background
		if (data.indent === 0) {
			value = "<strong>" + (value || "") + "</strong>";
		}

		// indent 2 — Bill row: grey italic
		if (data.indent === 2) {
			value = "<span style='color:#555;font-style:italic'>" + (value || "") + "</span>";
		}

		// Claim status colours (indent 1 only)
		if (column.fieldname === "claim_status" && data.indent === 1) {
			if (data.claim_status === "Approved") {
				value = "<span style='color:green;font-weight:bold'>" + data.claim_status + "</span>";
			} else if (
				data.claim_status === "Rejected" ||
				data.claim_status === "Declined by Officer" ||
				data.claim_status === "Declined by Manager" ||
				data.claim_status === "Cancelled by Manager" ||
				data.claim_status === "Cancelled by Officer"
			) {
				value = "<span style='color:red;font-weight:bold'>" + data.claim_status + "</span>";
			} else if (
				data.claim_status === "Submitted" ||
				data.claim_status === "Accepted by Officer" ||
				data.claim_status === "Accepted by Manager" ||
				data.claim_status === "Sent to Doctor"
			) {
				value = "<span style='color:#1f6fbf'>" + data.claim_status + "</span>";
			} else if (data.claim_status === "Draft") {
				value = "<span style='color:orange'>" + data.claim_status + "</span>";
			}
		}

		// Assessment colours on bill rows (indent 2)
		if (column.fieldname === "claim_status" && data.indent === 2) {
			if (data.claim_status === "Accepted") {
				value = "<span style='color:green;font-style:italic'>" + data.claim_status + "</span>";
			} else if (data.claim_status === "Declined") {
				value = "<span style='color:red;font-style:italic'>" + data.claim_status + "</span>";
			}
		}

		if (
			(column.fieldname === "checked_by_officer" || column.fieldname === "checked_by_manager")
			&& data.indent === 1
		) {
			let v = data[column.fieldname];
			if (v === "Accepted") value = "<span style='color:green'>" + v + "</span>";
			else if (v === "Declined") value = "<span style='color:red'>" + v + "</span>";
		}

		return value;
	},

	onload: function (report) {
	    frappe.db.get_list("Claim Summary", {
			fields: ["name"],
			order_by: "creation desc",
			limit: 1
		}).then((res) => {
			if (res && res.length > 0) {
				report.set_filter_value("group_month", res[0].name);
			}
		});
	
		frappe.query_reports["Monthly Group Report - Insurance"]._report_obj = report;

		// Primary "Print Report" button — always visible
		report.page.set_primary_action(__("Print Report"), function () {
			//trigger_print_for_report(report, null);
			open_print_window_all(report);
		}, "fa fa-print");

		// Secondary "Print All" button
		//report.page.add_action_item(__("Print All Employees"), function () {
		//	open_print_window_all(report);
		//});

		// Delegate clicks on inline row print buttons
		report.page.wrapper.on("click", ".btn-print-emp-row", function (e) {
			e.stopPropagation();
			let row_index = parseInt($(this).data("row-index"), 10);
			trigger_print_for_report(report, row_index);
		});
	},

	after_datatable_render: function (datatable_obj) {
		let report = frappe.query_reports["Monthly Group Report - Insurance"]._report_obj;
		if (!report) return;

		$(datatable_obj.wrapper || datatable_obj.bodyScrollable).find(".dt-row").each(function () {
			let row_index = $(this).attr("data-row-index");
			if (row_index === undefined) return;

			let row_data = report.data && report.data[parseInt(row_index, 10)];
			if (!row_data || row_data.indent !== 0) return;

			if ($(this).find(".btn-print-emp-row").length) return;

			let first_cell = $(this).find(".dt-cell__content").first();
			first_cell.append(
				"<button class='btn btn-default btn-xs btn-print-emp-row'"
				+ " data-row-index='" + row_index + "'"
				+ " title='Print " + (row_data.name || "") + " - " + (row_data.claim_type || "") + "'"
				+ " style='margin-left:10px;padding:1px 6px;font-size:10px;line-height:1.4;vertical-align:middle;'>"
				+ "<i class='fa fa-print'></i>"
				+ "</button>"
			);
		});
	}
};

// ── Claim type constant used for print ordering ────────────────────────────
const CLAIM_TYPE_SURGICAL = "Surgical and hospital expenses claim";

// ── Resolve target row (by index) and open print ────────────────────────────
// row_index identifies the exact indent-0 block clicked. Blocks can no
// longer be matched by employee name/id alone: one employee legitimately
// produces separate blocks for each form type (OPD, Surgical, etc.), and
// those blocks share the same employee id. Row position is the only
// reliable identifier.
function trigger_print_for_report(report, row_index) {
	let rows = report.data || [];
	let target_index = null;

	if (row_index !== null && row_index !== undefined && !isNaN(row_index)) {
		if (rows[row_index] && rows[row_index].indent === 0) {
			target_index = row_index;
		}
	} else {
		let parent_indices = [];
		rows.forEach(function (r, idx) {
			if (r.indent === 0) parent_indices.push(idx);
		});

		if (!parent_indices.length) {
			frappe.msgprint(__("No employee data found in the report."));
			return;
		}
		if (parent_indices.length === 1) {
			target_index = parent_indices[0];
		} else {
			frappe.msgprint(__(
				"Multiple claim groups shown (an employee may have more than one "
				+ "form type). Click the <i class='fa fa-print'></i> icon on a "
				+ "specific row, or use Print All Employees."
			));
			return;
		}
	}

	if (target_index === null) {
		frappe.msgprint(__("No matching row found to print."));
		return;
	}

	let target_row = rows[target_index];
	let claim_rows = collect_claims_with_bills(rows, target_index);
	open_print_window_single(target_row, claim_rows);
}

// ── Collect claims (indent 1) + bills (indent 2) belonging to ONE block ────
// start_index is the position of that block's indent-0 row. The report's
// Python script always emits a block's rows contiguously (all of one
// employee/form-type's claims and bills, in full, before moving to the next
// block), so the next indent-0 row encountered - regardless of what
// employee name it carries - always marks the end of this block. This is
// what makes the collection immune to two blocks sharing the same employee
// id.
function collect_claims_with_bills(rows, start_index) {
	let claims = [];
	let current_claim = null;

	for (let i = start_index + 1; i < rows.length; i++) {
		let r = rows[i];

		if (r.indent === 0) break;

		if (r.indent === 1) {
			current_claim = {
				name: r.name,
				employee: r.employee,
				insurance_period: r.insurance_period,
				claim_type: r.claim_type,
				claim_status: r.claim_status,
				checked_by_officer: r.checked_by_officer,
				checked_by_manager: r.checked_by_manager,
				amount_m: r.amount_m,
				amount: r.amount,
				agrahara_settled_amount: r.agrahara_settled_amount,
				amount_s: r.amount_s,
				bills: []
			};
			claims.push(current_claim);
		}

		if (r.indent === 2 && current_claim) {
			current_claim.bills.push({
				bill_no:       r.name,
				issue_date:   r.issue_date,
				purpose:       r.purpose,
				doctors_name:  r.checked_by_officer,
				patiants_name: r.employee_name,
				amount:        r.amount_m,
				assessment:    r.claim_status,
				remark:        r.checked_by_manager,
				category:      r.insurance_period
			});
		}
	}
	return claims;
}

// ── Print a single employee/form-type block ────────────────────────────────
function open_print_window_single(emp_row, claim_rows) {
	let now = frappe.datetime.now_datetime();
	let body_html = build_employee_page(emp_row, claim_rows, now);

	let print_html =
		"<html><head><title>Claim Report - " + (emp_row.name || "") + "</title>"
		+ get_print_styles()
		+ "</head><body>"
		+ "<div class='no-print' style='text-align:center;margin:14px'>"
		+ "<button onclick='window.print()' style='padding:8px 28px;font-size:12pt;"
		+ "cursor:pointer;background:#000;color:#fff;border:none;border-radius:4px;'>"
		+ "&#128424; Print</button>"
		+ "<div style='margin-top:8px;font-size:9pt;color:#a00'>"
		+ "In the print dialog, open <strong>More settings</strong> and switch "
		+ "<strong>Headers and footers</strong> OFF, otherwise the browser's own page "
		+ "numbers will overlap the ones printed on this form.</div>"
		+ "</div>"
		+ body_html
		+ "</body></html>";

	let w = window.open("", "_blank");
	w.document.write(print_html);
	w.document.close();
	w.focus();
}

// ── Print all blocks, grouped by claim type ─────────────────────────────
// Ordering rule: ALL claims where claim_type = "Surgical and hospital
// expenses claim" are printed first, then ALL other claims (OPD/Test/
// Spectacles, or anything else) are printed after.
//
// Each indent-0 row in report.data is now already exactly one employee's
// one form-type block (see the report's Python script), so this just walks
// every indent-0 row by its index, collects that block's own claims via
// collect_claims_with_bills, and buckets the resulting page into the
// Surgical or "other" list based on the claims' own claim_type - never by
// matching employee name.
//
// Page numbering still resets to 1 within each page-block, still correctly
// spans multiple physical pages if a block's bill list needs more than one
// sheet, and a trailing blank sheet is still inserted whenever a block's
// page count is odd, so the next block always starts on a fresh sheet.
function open_print_window_all(report) {
	let rows = report.data || [];
	if (!rows.length) { frappe.msgprint(__("No data to print.")); return; }

	let now = frappe.datetime.now_datetime();

	let surgical_pages = [];
	let other_pages = [];

	rows.forEach(function (emp, idx) {
		if (emp.indent !== 0) return;

		let all_claims = collect_claims_with_bills(rows, idx);

		let surgical_claims = all_claims.filter(function(c) {
			return c.claim_type === CLAIM_TYPE_SURGICAL;
		});
		let other_claims = all_claims.filter(function(c) {
			return c.claim_type !== CLAIM_TYPE_SURGICAL;
		});

		if (surgical_claims.length) {
			let surgical_emp_row = Object.assign({}, emp, { claim_type: CLAIM_TYPE_SURGICAL });
			surgical_pages.push(build_employee_page(surgical_emp_row, surgical_claims, now));
		}

		if (other_claims.length) {
			// All non-Surgical claim_type values currently render on the same
			// OPD-style form layout, so any one of them (the first) is enough
			// to drive the header/layout branch in build_employee_page.
			let other_emp_row = Object.assign({}, emp, { claim_type: other_claims[0].claim_type });
			other_pages.push(build_employee_page(other_emp_row, other_claims, now));
		}
	});

	let all_pages = surgical_pages.concat(other_pages).join("");

	if (!all_pages) { frappe.msgprint(__("No employee rows found.")); return; }

	let print_html =
		"<html><head><title>Claim Report - All Employees</title>"
		+ get_print_styles()
		+ "</head><body>"
		+ "<div class='no-print' style='text-align:center;margin:14px;font-size:9pt;color:#a00'>"
		+ "In the print dialog, open <strong>More settings</strong> and switch "
		+ "<strong>Headers and footers</strong> OFF, otherwise the browser's own page "
		+ "numbers will overlap the ones printed on each form."
		+ "</div>"
		+ all_pages
		+ "</body></html>";

	let w = window.open("", "_blank");
	w.document.write(print_html);
	w.document.close();
	w.focus();
	w.print();
}

// ── Build one block's print page(s) ────────────────────────────────────────
// Long bill lists are explicitly split into multiple .employee-page blocks here
// (rather than letting the browser silently overflow one tall div onto a second
// physical sheet), so every physical page gets its own correct "Page X of Y".
// If the resulting page count for this employee is odd, one additional fully
// blank A4 sheet (no header, no footer, no page number, no text at all) is
// appended so the next employee's form always starts on a new physical sheet
// (useful when printouts are later separated/stapled per employee, or printed
// duplex).
function build_employee_page(emp_row, claim_rows, now) {
	// Estimated max bill rows that comfortably fit one A4 page at the current
	// font/row sizing. Capacity depends on what else shares the page:
	//   ROWS_PLAIN            - only the items table (no header, no office-box)
	//   ROWS_WITH_HEADER      - title/employee-id header + items table (first
	//                           page of a multi-page form, office-box lands later)
	//   ROWS_WITH_OFFICE      - items table + Grand Total + office-use box
	//                           (last page of a multi-page form, no header)
	//   ROWS_HEADER_AND_OFFICE- header + items table + office-use box, all on
	//                           one sheet (a form that fits on a single page) —
	//                           the smallest budget since it carries everything
	// Tune these four numbers if a real printed page ever overflows or looks
	// too empty.
	const ROWS_PLAIN = 18;
	const ROWS_WITH_HEADER = 18;
	const ROWS_WITH_OFFICE = 15;
	const ROWS_HEADER_AND_OFFICE = 10;

	let grand_total_opd = 0;
	claim_rows.forEach(function(claim) {
		grand_total_opd = grand_total_opd + (claim.amount_m || 0);
	});

	// Flatten claim -> bills into one ordered list of print rows
	let flat_rows = [];
	claim_rows.forEach(function(claim) {
		if (claim.bills && claim.bills.length) {
			claim.bills.forEach(function(bill) {
				flat_rows.push({ claim_name: claim.name, bill: bill });
			});
		} else {
			flat_rows.push({ claim_name: claim.name, bill: null });
		}
	});

	// Whether this employee has any real bill rows at all (as opposed to
	// only placeholder "claim with no bills" entries). Used below to tell a
	// genuinely bill-less page apart from a trailing page that's empty only
	// because all the bills were already printed on an earlier page.
	let has_any_bills = flat_rows.some(function(r) { return !!r.bill; });

	// Split into page-sized chunks. The very first chunk always carries the
	// header; the very last chunk always carries the Grand Total + office-use
	// box. If it's the same chunk (single page), use the smallest budget that
	// accounts for both at once.
	let chunks = [];
	let remaining = flat_rows.slice();

	if (remaining.length <= ROWS_HEADER_AND_OFFICE) {
		// Fits on one page carrying both the header and the office-box.
		chunks.push(remaining);
	} else {
		// First page: header, but office-box lands on a later page.
		chunks.push(remaining.splice(0, ROWS_WITH_HEADER));

		// Middle pages: neither header nor office-box.
		while (remaining.length > ROWS_WITH_OFFICE) {
			chunks.push(remaining.splice(0, ROWS_PLAIN));
		}

		// Last page: office-box, but no header.
		chunks.push(remaining);
	}

	if (chunks.length === 0) chunks.push([]);

	let total_pages = chunks.length;
	let bill_serial = 0;
	let pages_html = "";

	chunks.forEach(function(chunk, page_index) {
		let is_last_page = (page_index === total_pages - 1);
		let rows_html = "";

		if (chunk.length === 0) {
			rows_html = has_any_bills
				// This page is empty only because every bill row was already
				// printed on an earlier page (e.g. the header page had room
				// for all of them, but the office-box still needed its own
				// sheet). Nothing more to list here — leave the table body
				// empty and let the Grand Total / office-box speak for it.
				? ""
				// This employee has no bill records at all.
				: "<tr><td colspan='8' style='color:#aaa;font-style:italic;padding-left:16px'>"
					+ "No bill details</td></tr>";
		} else {
			chunk.forEach(function(row) {
				if (row.bill) {
					bill_serial = bill_serial + 1;
					let bill = row.bill;
					rows_html +=
						"<tr>"
						+ "<td style='color:#555'>" + bill_serial + "</td>"
						+ "<td style='color:#555'>" + row.claim_name + "</td>"
						+ "<td style='color:#555'>" + (bill.issue_date || "") + "<br>" + (bill.bill_no || "") + "</td>"
						+ "<td style='color:#555'>" + (bill.purpose || "") + "</td>"
						+ "<td style='color:#555'>" + (bill.patiants_name || "") + "</td>"
						+ "<td style='text-align:right;color:#555'>" + fmt_currency(bill.amount) + "</td>"
						+ "<td></td>"
						+ "<td></td>"
						+ "</tr>";
				} else {
					rows_html +=
						"<tr><td colspan='8' style='color:#aaa;font-style:italic;padding-left:16px'>"
						+ "No bill details (" + row.claim_name + ")</td></tr>";
				}
			});
		}

		let footer_extra_html = "";
		if (is_last_page) {
			footer_extra_html =
				"<tr style='border-top:2px solid #000'>"
				+ "<td colspan='5'><strong>Grand Total</strong></td>"
				+ "<td style='text-align:right'><strong>" + fmt_currency(grand_total_opd) + "</strong></td>"
				+ "</tr>";
		}

		let final_total = grand_total_opd;

		if (emp_row.claim_type === CLAIM_TYPE_SURGICAL) {
			// claim_rows here has already been filtered to this employee's
			// Surgical claims only (see open_print_window_all), so sum
			// amount_s straight from them rather than trusting emp_row.amount_s,
			// which is an unfiltered total across ALL of the employee's claims.
			let grand_total_s = 0;
			claim_rows.forEach(function(claim) {
				grand_total_s = grand_total_s + (claim.amount_s || 0);
			});
		    final_total = grand_total_s;
		}


		let office_box_html = "";
		if (is_last_page) {
			office_box_html =
				"<div class='office-box'>"
				+ "<h4>{ For Office Use Only }</h4>"
				+ "<p style='font-size:12px; font-weight:bold; margin-bottom:6px;'>"
				+ "Recommendation of the Head of the Department</p>"
				+ "<p style='font-size:12px;'>"
				+ "After considering the medical certificates, receipts and other information provided "
				+ "by the applicant in relation to the Medical treatment received, I recommend the "
				+ "reimbursement of total expenses / an amount of "
				+ "Rs. <strong>" + fmt_currency(final_total) + "</strong> of total expenses incurred by him/her in this connection, subject to the conditions applied by the UCSC insurance policy. </p>"
				+ "<table style='width:100%; margin-top:10px; font-size:12px;'>"
				+ "<tr>"
				+ "<br>"
				+ "<td style='width:40%'> ……………………<br>"
				+ "<small style='font-size: 11px;'>Date</small>"
				+ "</td>"
				+ "<td style='text-align:right;'>……………………………………………<br>"
				+ "<small style='font-size: 11px;'>Signature of the Administrative Officer in-charge of<br>UCSC Staff Medical Support Scheme</small>"
				+ "</td>"
				+ "</tr>"
				+ "</table>"
				+ "<div style='margin-top:14px; border-top:1px dashed #aaa; padding-top:10px; font-size:12px;'>"
				+ "The information given by the applicant and the document attached herewith have been checked and Recommended / Not Recommended reimbursement of the total approved expenses."
				+ "</div>"
				+ "<div style='margin-top:14px; padding-top:10px; font-size:12px;'>"
				+ "Total Approved Amount……………………………………"
				+ "</div>"
				+ "<table style='width:100%; margin-top:10px; font-size:12px;'>"
				+ "<tr>"
				+ "<td style='width:40%'>……………………………<br>"
				+ "<small style='font-size: 11px;'>Date</small>"
				+ "</td>"
				+ "<td style='text-align:right'>………………………………………………<br>"
				+ "<small style='font-size: 11px;'>Academic Staff member of the Medical Faculty (Seal)</small>"
				+ "</td>"
				+ "</tr>"
				+ "</table>"
				+ "</div>";
		}
		
		let scheme_period = "2026";

		let header_html = "";
		if (page_index === 0) {
			// Full title + employee identification only on the first page of this employee
			header_html =
				"<div class='form-title'>";

			if (emp_row.claim_type !== CLAIM_TYPE_SURGICAL) {
    			header_html +=
    			    "<h3>University of Colombo School of Computing</h3>"
                    + "<h3>Staff Medical Support Scheme \u2013 " + scheme_period + "</h3>"
                    + "<h3>Reimbursement of Medical Expenses(OPD Treatment/ Test/ Spectacles)</h3>";
                    
    				//"<h3>STAFF MEDICAL SUPPORT SCHEME \u2013 2026</h3>"
    				//+ "<h3>APPLICATION FOR REIMBURSEMENT OF MEDICAL EXPENSES</h3>"
    				//+ "<h3>OPD TREATMENT/SPECTACLES</h3>";
			}

			header_html +=
				"</div>"
				+ "<table class='employee-section'>"
				+ "<tr>"
				+ "<td><strong>Employee ID:</strong>&nbsp;" + (emp_row.name || "") + "</td>"
				+ "<td><strong>Employee Name:</strong>&nbsp;" + (emp_row.employee_name || "") + "</td>"
				+ "<td style='text-align:right'><strong>Group No:</strong>&nbsp;" + (emp_row.group_no || "") + "</td>"
				+ "</tr></table>";

			if (emp_row.claim_type === CLAIM_TYPE_SURGICAL) {
    			header_html +=
    				 "<table class='employee-section'>"
    				+ "<tr>"
    				+ "<td></td>"
    				+ "<td></td>"
    				+ "<td style='text-align:right'><strong>Claim No:</strong>&nbsp;" + (chunk[0].claim_name || "") + "</td>"
    				+ "</tr></table>";
			}

			if (emp_row.claim_type !== CLAIM_TYPE_SURGICAL) {
    			header_html +=
    				 "<div class='section-title'> Details Of Bills</div>";
			}
		}

		pages_html += "<div class='employee-page'>"
			+ "<div class='print-meta'>" + (now || "") + "</div>"

			+ header_html;

			if (emp_row.claim_type !== CLAIM_TYPE_SURGICAL) {
                pages_html +=
        			"<table class='items-table'>"
        			+ "<thead><tr>"
        			+ "<th style='width:2%'>No</th>"
        			+ "<th style='width:19%'>Claim No</th>"
        			+ "<th style='width:14%'>Bill Date / No</th>"
        			+ "<th style='width:16%'>Description / Purpose</th>"
        			+ "<th style='width:12%'>Patient</th>"
        			+ "<th style='width:9%;text-align:right'>Amount(Rs.)</th>"
        			+ "<th style='width:10%'>Approved Amount</th>"
        			+ "<th style='width:14%'>Remark</th>"
        			+ "</tr></thead>"
        			+ "<tbody>" + rows_html + footer_extra_html + "</tbody>"
        			+ "</table>";
			}

        pages_html +=
			office_box_html;

			// Page number footer — resets to "1 of N" at the start of each employee
			if (emp_row.claim_type === CLAIM_TYPE_SURGICAL) {
			    pages_html +=
        			 "<div class='page-footer'>Page " + 3 + " of " + 3 + "</div>"

        			+ "</div>";
			} else {
			    pages_html +=
        			 "<div class='page-footer'>Page " + (page_index + 1) + " of " + total_pages + "</div>"

        			+ "</div>";
			}

	});

	// ── Blank filler page ──────────────────────────────────────────────────
	// If this employee ended up with an odd number of printed pages, append
	// one completely blank A4 sheet — no header, no footer, no page number,
	// no text — so the next employee always starts on a new physical sheet.
	if (total_pages % 2 !== 0) {
		pages_html += "<div class='employee-page blank-page'></div>";
	}

	return pages_html;
}

