		report.page.set_primary_action(__("Print Report"), function () {
			print_summary_report(report);
		}, "fa fa-print");
	}
};

// NOTE: the old code that used to live here -
//   let group_month = report.get_filter_value("group_month").split("-");
//   let scheme_period = group_month[1];
//   let scheme_month = group_month[0];
//   const SCHEME_NAME = "Staff Medical Support Scheme – " + scheme_period;
// - ran at the top level of this file, outside any function. `report` is
// only ever available as a parameter passed into callbacks like
// onload(report); it does not exist as a global. That line threw
// `ReferenceError: report is not defined` the instant this script loaded,
// which in turn meant scheme_period/scheme_month/SCHEME_NAME (all
// let/const) never got past their declaration - so the very first click on
// "Print Report" threw a second error ("Cannot access 'SCHEME_NAME' before
// initialization") trying to use them. There was also a second, separate
// bug: group_month[1]/group_month[0] were swapped - for a name like
// "2026-08" that assigned period="08" and month="2026", backwards.
//
// Fix: only compute these inside print_summary_report(report), where
// `report` actually exists, and recompute them on every print so they
// always reflect whichever Group Month is currently selected rather than
// whatever happened to be selected when the page first loaded.

const INSTITUTION_NAME = "UNIVERSITY OF COLOMBO SCHOOL OF COMPUTING";

function print_summary_report(report) {
