	// (scheme_period), index 1 is the month (scheme_month).
	let scheme_period = group_month_parts[0] || "";
	let scheme_month = group_month_parts[1] || "";
	let scheme_name = "Staff Medical Support Scheme – " + scheme_period;

	let surgical_rows = rows;

	let surgical_total = surgical_rows.reduce((sum, r) => sum + (r.grand_total || 0), 0);
