	let other_table_html = "";
	//if (other_rows.length) {
	//	other_table_html = build_summary_table("Reimbursement of medical expenses(OPD treatment/ Test/ Spectacles)", other_rows, other_total);
	//}

	// Signature space (Approved / Recommended / Received) shown directly
	// under the claims table.
	let signature_block_html = build_signature_block();

	let today = frappe.datetime.str_to_user(frappe.datetime.get_today());
	
	let footer_context = "<div class='section-label'>Summary of Recommended Claims</div>"
		+ "<table class='summary-table'>"
		+ "<tr><td style='width:5%; text-align:center;'>1</td><td>EMPLOYEES COVERED</td><td>" + stats.employees + "</td><td style='width:50%;'></td></tr>"
		+ "<tr><td style='width:5%; text-align:center;'>2</td><td>TOTAL CLAIM GROUPS</td><td>" + stats.claims + "</td><td style='width:50%;'></td></tr>"
		+ "<tr class='grand-row'><td style='width:5%; text-align:center;'>3</td><td>GRAND TOTAL RECOMMENDED</td><td>Rs. " + fmt_currency(stats.grand_total) + "</td><td style='width:50%;'></td></tr>"
		+ "</table>"
    	+ "<div class='sign-block'>"
		+ "<table class='sign-table'>"
		+ "<tr>"
		+ "<td style='width:46%;'>"
		+ "<div class='sign-line-title'>PREPARED / REVIEWED BY</div>"
		+ "<div class='sign-space'></div>"
		+ "<div class='sign-border'></div>"
		+ "<div class='role'>Signature of the Administrative Officer in-charge of<br>UCSC Staff Medical Support Scheme</div>"
		+ "<div class='date-field'>Date: " + today + "</div>"
		+ "</td>"
		+ "<td style='width:8%;'></td>"
		+ "<td style='width:46%;'>"
		+ "<div class='sign-line-title'>Received BY</div>"
		+ "<div class='sign-space'></div>"
		+ "<div class='sign-border'></div><br>"
		+ "<div class='role'>Name: ______________________________________________</div><br>"
		+ "<div class='role'>Designation: _________________________________________</div>"
		+ "<div class='date-field'>Date: _______________________________________________</div>"
		+ "</td>"
		+ "</tr>"
		+ "</table>"
		+ "</div>";
	
	const now_dt = new Date();
    const formattedDate = `${now_dt.getFullYear()}-${String(now_dt.getMonth() + 1).padStart(2, '0')}-${String(now_dt.getDate()).padStart(2, '0')} ${String(now_dt.getHours()).padStart(2, '0')}:${String(now_dt.getMinutes()).padStart(2, '0')}:${String(now_dt.getSeconds()).padStart(2, '0')}`;

	let body_html =
		"<div class='sheet'>"
		//+ get_doc_header_html(now)
		+ "<div class='print-meta'>" + formattedDate +"</div>"
		+ "<div class='doc-title'><h3>University of Colombo School of Computing</h3>"
        + "<h3>Staff Medical Support Scheme \u2013 " + scheme_period + "</h3>"
		+ "<div class='sub'>Insurance Approved Summary " + scheme_period + "\u2013" + scheme_month + "</div></div>"
		+ surgical_table_html
		+ other_table_html
		+ signature_block_html
	//	+ footer_context
		+ "<div class='page-footer'><span></span><span>Page 1 of 1</span></div>"
		+ "</div>";

	let print_html = wrap_print_document("Insurance Summary Report", body_html, true);

	let w = window.open("", "_blank");
	w.document.write(print_html);
