	w.focus();
}

// CHANGED: the printed summary table used to show r.group_no under a
// "Group No." header. The report's actual tracked/visible column is now
// purchase_order (see the CSV export - Employee No. / Employee Name /
// Purchase Order No. / Grand Total), so the print output is switched to
// match: r.purchase_order under a "Purchase Order No." header.
function build_summary_table(title, rows, subtotal) {
	if (!rows.length) return "";

	let rows_html = rows.map(function (r, index) {
		return "<tr>"
		    + "<td style='text-align:center;'>" + (index + 1) + "</td>"
			+ "<td>" + (r.employee_no || "") + "</td>"
			+ "<td>" + (r.employee_name || "") + "</td>"
			+ "<td>" + (r.purchase_order || "") + "</td>"
			+ "<td>" + (r.group_no || "") + "</td>"
			+ "<td class='num'>" + fmt_currency(r.grand_total) + "</td>"
			+ "</tr>";
	}).join("");

	return (
		"<div class='section-label'>" + title + "</div>"
		+ "<table class='report-table'>"
		+ "<thead><tr>"
		+ "<th style='width:5%; text-align:center;'>#</th>"
		+ "<th style='width:10%'>Emp No.</th>"
		+ "<th style='width:20%'>Employee Name</th>"
		+ "<th style='width:30%'>Purchase Order No.</th>"
		+ "<th style='width:20%'>Claim Group No.</th>"
		+ "<th style='width:15%; text-align:right;'>Amount (Rs)</th>"
		+ "</tr></thead>"
		+ "<tbody>" + rows_html
		+ "<tr class='subtotal-row'><td colspan='4'>SUBTOTAL</td><td class='num'>" + fmt_currency(subtotal) + "</td></tr>"
		+ "</tbody></table>"
	);
}

