		+ "background:#000;color:#fff;border:none;border-radius:2px;'>Print Document</button></div>";

	let auto_print_script = auto_open_dialog
		? "<script>window.onload = function () { window.print(); };<\/script>"
		: "";

	return (
		"<!DOCTYPE html><html><head><title>" + title + "</title>" + get_print_styles() + "</head><body>"
		+ print_button + hint + body_html + auto_print_script + "</body></html>"
