function fmt_currency(val) {
	if (!val) return "0.00";
	return parseFloat(val).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// v16: report JS is evaluated inside an IIFE, so expose this for the Claim Summary form script
window.print_summary_report_insurance_approved_summary = print_summary_report;

frappe.query_reports["Details Report - Medical Claim"] = {
	filters: [
		{ fieldname: "group_month",	label: __("Group Month"), fieldtype: "Link", options: "Claim Summary" }
	],
	
	onload: function(report) {
		report.page.add_inner_button(__("Download"), function() {
			generate_pdf(report);
		});
	}
};

function generate_pdf(report) {
	let data = report.data;
	let columns = report.columns;

	if (!data || !data.length) {
		frappe.msgprint(__("No data to export. Please run the report first."));
		return;
	}

	let filters = report.get_values();
	let group_month = filters.group_month || "";

	let range = get_month_range(group_month);
	let period_text = group_month ? `${range.first} to ${range.last}` : "";

	let header_html = columns.map(col =>
		`<th>${frappe.utils.escape_html(col.label)}</th>`
	).join("");

	let rows_html = data.map(row => {
		let is_total = row.employee_name === "Total";

		let tds;
		if (is_total) {
			let rest_tds = columns.slice(2).map(col => {
				let val = row[col.fieldname];
				if (val === undefined || val === null) val = "";
				if (col.fieldtype === "Float" && val !== "") val = format_number(val);
				let align = col.fieldtype === "Float" ? "right" : "left";
				return `<td style="text-align:${align};">${val}</td>`;
			}).join("");

			tds = `<td colspan="2" style="text-align:center;">Total</td>${rest_tds}`;
		} else {
			tds = columns.map(col => {
				let val = row[col.fieldname];
				if (val === undefined || val === null) val = "";
				if (col.fieldtype === "Float" && val !== "") val = format_number(val);
				let align = col.fieldtype === "Float" ? "right" : "left";
				return `<td style="text-align:${align};">${val}</td>`;
			}).join("");
		}

		return `<tr class="${is_total ? "total-row" : ""}">${tds}</tr>`;
	}).join("");

	let html = `<!DOCTYPE html>
        <html>
        <head>
        <meta charset="utf-8">
        <style>
        	* { font-family: Arial, Helvetica, sans-serif; font-weight: normal; }
        	@page { size: A4 landscape; margin: 12mm; }
        	body { color: #000; margin: 0; font-size: 10px; }
        	.header { text-align: center; padding-bottom: 10px; margin-bottom: 6px; }
        	.header h2 { margin: 0; color: #000; font-size: 14px; }
        	.header h3 { margin: 4px 0; color: #000; font-size: 12px; }
        	.header .meta { font-size: 10px; color: #000; }
        	table { width: 100%; border-collapse: collapse; }
        	th, td { border: 1px solid #666; padding: 4px 6px; font-size: 10px; }
        	thead th { background: #fff; color: #000; }
        	tbody tr:nth-child(even) { background: #fff; }
        	tr.total-row { background: #fff; }
        	thead { display: table-header-group; }
        	tr { page-break-inside: avoid; }
        </style>
        </head>
        <body>
        	<div class="header">
        		<h3>UNIVERSITY OF COLOMBO SCHOOL OF COMPUTING</h3>
        		<h3>Medical Suport Scheme - Scheme I/II/III</h3>
        		<h3>For the Period ${frappe.utils.escape_html(period_text)}</h3>
        	</div>
        	<table>
        		<thead><tr>${header_html}</tr></thead>
        		<tbody>${rows_html}</tbody>
        	</table>
        	<script>
        		window.onload = function() {
        			window.print();
        		};
        	</script>
        </body>
        </html>`;

	let win = window.open("", "_blank");
	win.document.open();
	win.document.write(html);
	win.document.close();
}

function format_number(val) {
	return parseFloat(val).toLocaleString("en-US", {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2
	});
}

function get_month_range(group_month) {
	if (!group_month) return { first: "", last: "" };

	let [year, month] = group_month.split("-").map(Number);

	let first_day = new Date(year, month - 1, 1);
	let last_day = new Date(year, month, 0);

	function format(d) {
		let y = d.getFullYear();
		let m = String(d.getMonth() + 1).padStart(2, "0");
		let day = String(d.getDate()).padStart(2, "0");
		return `${y}/${m}/${day}`;
	}

	return {
		first: format(first_day),
		last: format(last_day)
	};
}

report_script:
CLAIM_TYPE_SURGICAL = "Surgical and hospital expenses claim"

db_filters = [["docstatus", "<", 2]]
db_filters.append(["claim_status", "=", filters.get("claim_status") or "Approved"])

if not filters.get("group_month"):
    frappe.throw("Please select a Group Month to run this report.")

db_filters.append(["summary", "=", filters["group_month"]])

if filters.get("claim_group"):
	db_filters.append(["claim_group", "=", filters["claim_group"]])

results = frappe.db.get_list(
	"Claim Approval",
	filters=db_filters,
	fields=["name", "summary", "employee", "claim_group", "claim_no", "purchase_order", "approved_amount", "category"],
	order_by="employee asc, creation asc",
	ignore_permissions=False
)

non_surgical_parents = []
for row in results:
	if not row.get("claim_no"):
		non_surgical_parents.append(row.get("name"))

child_rows = []
if non_surgical_parents:
	child_rows = frappe.db.get_all(
		"Approved Bill Amounts",
		filters={"parent": ["in", non_surgical_parents]},
		fields=["parent", "category", "approved_amount"]
	)

child_by_parent = {}
for crow in child_rows:
	cat = (crow.get("category") or "Uncategorized").strip()
	child_by_parent.setdefault(crow.get("parent"), []).append(
		(cat, crow.get("approved_amount") or 0)
	)

category_docs = frappe.db.get_list(
	"Covers and Benefits",
	fields=["name"],
	order_by="name asc"
)

category_list = []
for cdoc in category_docs:
	category_list.append(cdoc.get("name"))

def category_fieldname(cat):
	safe = "".join(ch if ch.isalnum() else "_" for ch in cat.lower())
	while "__" in safe:
		safe = safe.replace("__", "_")
	return "cat_%s" % safe.strip("_")

category_fieldnames = []
for cat in category_list:
	category_fieldnames.append(category_fieldname(cat))

columns = [
	{"label": "Employee No.",   "fieldname": "employee_no", "fieldtype": "Data", "width": 160},
	{"label": "Name",  "fieldname": "employee_name", "fieldtype": "Data", "width": 180},
]

for cat, fname in zip(category_list, category_fieldnames):
	columns.append({"label": cat, "fieldname": fname, "fieldtype": "Float", "width": 140, "precision": 2})

columns.append({"label": "Total", "fieldname": "grand_total", "fieldtype": "Float", "width": 140, "precision": 2})

# Grouping key is now just the employee number - Surgical and Other rows
# for the same employee merge into one row instead of two.
groups = {}
group_order = []

for row in results:
	emp_key = frappe.db.get_value("Insurance Member", row.get("employee"), "employee") or ""
	is_surgical = bool(row.get("claim_no"))
	key = emp_key

	if key not in groups:
		group_order.append(key)
		emp_name = frappe.db.get_value("Insurance Member", row.get("employee"), "employee_name") or ""

		cats_init = {}
		for fname in category_fieldnames:
			cats_init[fname] = 0.0

		groups[key] = {
			"employee_name": emp_name,
			"grand_total": 0.0,
			"categories": cats_init
		}

	g = groups[key]

	g["grand_total"] = g["grand_total"] + (row.get("approved_amount") or 0)

	if is_surgical:
