frappe.query_reports["Summery Report - Medical Claim"] = {
	filters: [
		{ fieldname: "group_month",	label: __("Group Month"), fieldtype: "Link", options: "Claim Summary" }
	],
	
	onload: function(report) {
		report.page.add_inner_button(__("Download"), function() {
			generate_pdf(report);
		});
	}
};

function generate_pdf(report) {
	let data = report.data;
	let columns = report.columns;

	if (!data || !data.length) {
		frappe.msgprint(__("No data to export. Please run the report first."));
		return;
	}

	let filters = report.get_values();
	let group_month = filters.group_month || "";

	let range = get_month_range(group_month);
	let period_text = group_month ? `${range.first} to ${range.last}` : "";

	let header_html = columns.map(col =>
		`<th>${frappe.utils.escape_html(col.label)}</th>`
	).join("");

	let rows_html = data.map(row => {
		let is_total = row.employee_name === "Total";

		let tds = columns.map(col => {
				let val = row[col.fieldname];
				if (val === undefined || val === null) val = "";
				if (col.fieldtype === "Float" && val !== "") val = format_number(val);
				let align = col.fieldtype === "Float" ? "right" : "left";
				return `<td style="text-align:${align};">${val}</td>`;
			}).join("");

		return `<tr>${tds}</tr>`;
	}).join("");

	let html = `<!DOCTYPE html>
        <html>
        <head>
        <meta charset="utf-8">
        <style>
        	* { font-family: Arial, Helvetica, sans-serif; font-weight: normal; }
        	@page { size: A4 landscape; margin: 12mm; }
        	body { color: #000; margin: 0; font-size: 10px; }
        	.header { text-align: center; padding-bottom: 10px; margin-bottom: 6px; }
        	.header h2 { margin: 0; color: #000; font-size: 14px; }
        	.header h3 { margin: 4px 0; color: #000; font-size: 12px; }
        	.header .meta { font-size: 10px; color: #000; }
        	table { width: 100%; border-collapse: collapse; }
        	th, td { border: 1px solid #666; padding: 4px 6px; font-size: 10px; }
        	thead th { background: #fff; color: #000; }
        	tbody tr:nth-child(even) { background: #fff; }
        	thead { display: table-header-group; }
        	tr { page-break-inside: avoid; }
        </style>
        </head>
        <body>
        	<div class="header">
        		<h3>UNIVERSITY OF COLOMBO SCHOOL OF COMPUTING</h3>
        		<h3>Summery of Medical Suport Scheme</h3>
        		<h3>For the Period ${frappe.utils.escape_html(period_text)}</h3>
        	</div>
        	<table>
        		<thead><tr>${header_html}</tr></thead>
        		<tbody>${rows_html}</tbody>
        	</table>
        	<script>
        		window.onload = function() {
        			window.print();
        		};
        	</script>
        </body>
        </html>`;

	let win = window.open("", "_blank");
	win.document.open();
	win.document.write(html);
	win.document.close();
}

function format_number(val) {
	return parseFloat(val).toLocaleString("en-US", {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2
	});
}

function get_month_range(group_month) {
	if (!group_month) return { first: "", last: "" };

	let [year, month] = group_month.split("-").map(Number);

	let first_day = new Date(year, month - 1, 1);
	let last_day = new Date(year, month, 0);

	function format(d) {
		let y = d.getFullYear();
		let m = String(d.getMonth() + 1).padStart(2, "0");
		let day = String(d.getDate()).padStart(2, "0");
		return `${y}/${m}/${day}`;
	}

	return {
		first: format(first_day),
		last: format(last_day)
	};
}

report_script:
CLAIM_TYPE_SURGICAL = "Surgical and hospital expenses claim"

db_filters = [["docstatus", "<", 2]]
db_filters.append(["claim_status", "=", filters.get("claim_status") or "Approved"])

if not filters.get("group_month"):
    frappe.throw("Please select a Group Month to run this report.")

db_filters.append(["summary", "=", filters["group_month"]])

if filters.get("claim_group"):
	db_filters.append(["claim_group", "=", filters["claim_group"]])

results = frappe.db.get_list(
	"Claim Approval",
	filters=db_filters,
	fields=["name", "summary", "employee", "claim_group", "claim_no", "purchase_order", "approved_amount", "category"],
	order_by="employee asc, creation asc",
	ignore_permissions=False
)

non_surgical_parents = []
for row in results:
	if not row.get("claim_no"):
		non_surgical_parents.append(row.get("name"))

child_rows = []
if non_surgical_parents:
	child_rows = frappe.db.get_all(
		"Approved Bill Amounts",
		filters={"parent": ["in", non_surgical_parents]},
		fields=["parent", "category", "approved_amount"]
	)

child_by_parent = {}
for crow in child_rows:
	cat = (crow.get("category") or "Uncategorized").strip()
	child_by_parent.setdefault(crow.get("parent"), []).append(
		(cat, crow.get("approved_amount") or 0)
	)

category_docs = frappe.db.get_list(
	"Covers and Benefits",
	fields=["name"],
	order_by="name asc"
)

category_list = []
for cdoc in category_docs:
	category_list.append(cdoc.get("name"))

def category_fieldname(cat):
	safe = "".join(ch if ch.isalnum() else "_" for ch in cat.lower())
	while "__" in safe:
		safe = safe.replace("__", "_")
	return "cat_%s" % safe.strip("_")

category_fieldnames = []
for cat in category_list:
	category_fieldnames.append(category_fieldname(cat))

# Strips a trailing " - <year>" and is used as the actual grouping key,
# so schemes differing only by year merge into one column.
def scheme_display_name(scheme_name):
	parts = scheme_name.rsplit(" - ", 1)
	if len(parts) == 2 and parts[1].strip().isdigit():
		return parts[0].strip()
	return scheme_name

# Same slug approach as category_fieldname, but for scheme display
# names, since they become column fieldnames now.
def scheme_fieldname(scheme_disp):
	safe = "".join(ch if ch.isalnum() else "_" for ch in scheme_disp.lower())
	while "__" in safe:
		safe = safe.replace("__", "_")
	return "scheme_%s" % safe.strip("_")

scheme_docs = frappe.db.get_list(
	"Insurance Scheme",
	fields=["name"],
	order_by="name asc"
)

# Build the merged (by display name) scheme list up front.
scheme_display_list = []
seen_schemes = set()
for sdoc in scheme_docs:
	display_name = scheme_display_name(sdoc.get("name"))
	if display_name not in seen_schemes:
		seen_schemes.add(display_name)
		scheme_display_list.append(display_name)

scheme_display_list = sorted(scheme_display_list)

scheme_fieldnames = []
for disp in scheme_display_list:
	scheme_fieldnames.append(scheme_fieldname(disp))

# Columns: Category first, then one column per scheme, then Total.
columns = [
	{"label": "", "fieldname": "category", "fieldtype": "Data", "width": 200},
]

for disp, fname in zip(scheme_display_list, scheme_fieldnames):
	columns.append({"label": disp, "fieldname": fname, "fieldtype": "Float", "width": 140, "precision": 2})

columns.append({"label": "Total", "fieldname": "row_total", "fieldtype": "Float", "width": 140, "precision": 2})

# category_totals[category_fieldname][scheme_fieldname] = amount
category_totals = {}
for cfname in category_fieldnames:
	sub = {}
	for sfname in scheme_fieldnames:
		sub[sfname] = 0.0
	category_totals[cfname] = sub

emp_scheme_cache = {}

for row in results:
	employee = row.get("employee")

	if employee not in emp_scheme_cache:
		raw_scheme = frappe.db.get_value("Insurance Member", employee, "insurance_scheme") or "No Scheme"
		disp = scheme_display_name(raw_scheme)
		emp_scheme_cache[employee] = disp

		if disp not in scheme_display_list:
			scheme_display_list.append(disp)
			sfname = scheme_fieldname(disp)
			scheme_fieldnames.append(sfname)
			columns.insert(len(columns) - 1, {"label": disp, "fieldname": sfname, "fieldtype": "Float", "width": 140, "precision": 2})
			for cfname in category_fieldnames:
				category_totals[cfname][sfname] = 0.0

	disp = emp_scheme_cache[employee]
	sfname = scheme_fieldname(disp)
	is_surgical = bool(row.get("claim_no"))

	if is_surgical:
		cat = (row.get("category") or "Uncategorized").strip()
		amt = row.get("approved_amount") or 0
		cfname = category_fieldname(cat)
		if cfname in category_totals:
			category_totals[cfname][sfname] = category_totals[cfname].get(sfname, 0.0) + amt
	else:
		for cat, amt in child_by_parent.get(row.get("name"), []):
			cfname = category_fieldname(cat)
			if cfname in category_totals:
				category_totals[cfname][sfname] = category_totals[cfname].get(sfname, 0.0) + amt

data1 = []

# Column totals accumulated while building rows.
column_totals = {}
for sfname in scheme_fieldnames:
	column_totals[sfname] = 0.0
grand_total = 0.0

for cat, cfname in zip(category_list, category_fieldnames):
	row_out = {"category": cat}
	row_sum = 0.0
	for sfname in scheme_fieldnames:
		val = category_totals[cfname].get(sfname, 0.0)
		row_out[sfname] = val
		row_sum = row_sum + val
		column_totals[sfname] = column_totals[sfname] + val
	row_out["row_total"] = row_sum
	grand_total = grand_total + row_sum
	data1.append(row_out)

# Trailing Total row (column-wise totals + overall grand total)
total_row = {"category": "Total"}
for sfname in scheme_fieldnames:
	total_row[sfname] = column_totals[sfname]
total_row["row_total"] = grand_total
data1.append(total_row)

data = columns, data1

