};

const INSTITUTION_NAME = "UNIVERSITY OF COLOMBO SCHOOL OF COMPUTING";

function generate_pdf(report) {
	let rows = report.data || [];
	if (!rows.length) { frappe.msgprint(__("No data to print.")); return; }

	let now = frappe.datetime.now_datetime();

	let group_month_val = report.get_filter_value("group_month") || "";
	let group_month_parts = group_month_val.split("-");
	let scheme_period = group_month_parts[0] || "";
	let scheme_month = group_month_parts[1] || "";
	let scheme_name = "Staff Medical Support Scheme – " + scheme_period;

	let surgical_rows = rows;

	let surgical_total = surgical_rows.reduce((sum, r) => sum + (r.grand_total || 0), 0);

	let surgical_table_html = "";
	if (surgical_rows.length) {
		surgical_table_html = build_summary_table("", surgical_rows, surgical_total);
	}
	
	let stats = {
		employees: new Set(rows.filter(r => r.employee_no).map(r => r.employee_no)).size,
		claims: surgical_rows.length + 0,
		grand_total: surgical_total + 0
	};

	let today = frappe.datetime.str_to_user(frappe.datetime.get_today());

	const now_dt = new Date();
    const formattedDate = `${now_dt.getFullYear()}-${String(now_dt.getMonth() + 1).padStart(2, '0')}-${String(now_dt.getDate()).padStart(2, '0')} ${String(now_dt.getHours()).padStart(2, '0')}:${String(now_dt.getMinutes()).padStart(2, '0')}:${String(now_dt.getSeconds()).padStart(2, '0')}`;

	let body_html =
		"<div class='sheet'>"
		+ "<div class='print-meta'>" + formattedDate +"</div>"
		+ "<div class='doc-title'><h3>University of Colombo School of Computing</h3>"
        + "<h3>Staff Medical Support Scheme \u2013 " + scheme_period + "</h3>"
		+ "<div class='sub'>Insurance Approved Summary " + scheme_period + "\u2013" + scheme_month + "</div></div>"
		+ surgical_table_html
		+ "</div>";

	let print_html = wrap_print_document("Insurance Summary Report", body_html, true);

	let w = window.open("", "_blank");
	w.document.write(print_html);
	w.document.close();
	w.focus();
}

function build_summary_table(title, rows, subtotal) {
	if (!rows.length) return "";

	let rows_html = rows.map(function (r, index) {
		return "<tr>"
		    + "<td style='text-align:center;'>" + (index + 1) + "</td>"
			+ "<td>" + (r.employee_no || "") + "</td>"
			+ "<td>" + (r.employee_name || "") + "</td>"
			+ "<td>" + (r.purchase_order || "") + "</td>"
			+ "<td>" + (r.group_no || "") + "</td>"
			+ "<td class='num'>" + fmt_currency(r.grand_total) + "</td>"
			+ "</tr>";
	}).join("");

	return (
		"<div class='section-label'>" + title + "</div>"
		+ "<table class='report-table'>"
		+ "<thead><tr>"
		+ "<th style='width:5%; text-align:center;'>#</th>"
		+ "<th style='width:10%'>Emp No.</th>"
		+ "<th style='width:20%'>Employee Name</th>"
		+ "<th style='width:30%'>Purchase Order No.</th>"
		+ "<th style='width:20%'>Claim Group No.</th>"
		+ "<th style='width:15%; text-align:right;'>Amount (Rs)</th>"
		+ "</tr></thead>"
		+ "<tbody>" + rows_html
		+ "<tr class='subtotal-row'><td colspan='5' style='text-align:right;'>TOTAL</td><td class='num'>" + fmt_currency(subtotal) + "</td></tr>"
		+ "</tbody></table>"
	);
}

function get_doc_header_html(now, scheme_name) {
	return (
		"<table class='doc-header-table'>"
		+ "<tr>"
		+ "<td><strong>" + INSTITUTION_NAME + "</strong> — " + scheme_name + "</td>"
		+ "<td style='text-align:right;'>GEN: " + (now || "") + "</td>"
		+ "</tr>"
		+ "</table>"
	);
}

function wrap_print_document(title, body_html, auto_open_dialog) {
	let hint =
		"<div class='no-print' style='text-align:center;margin:10px;font-size:8pt;color:#555;'>"
		+ "In the print dialog, disable <strong>Headers and footers</strong> to prevent page number overlap.</div>";

	let print_button =
		"<div class='no-print' style='text-align:center;margin:10px'>"
		+ "<button onclick='window.print()' style='padding:6px 20px;font-size:10pt;font-weight:bold;cursor:pointer;"
		+ "background:#000;color:#fff;border:none;border-radius:2px;'>Print Document</button></div>";

	let auto_print_script = auto_open_dialog
		? "<script>window.onload = function () { window.print(); };<\/script>"
		: "";

	return (
		"<!DOCTYPE html><html><head><title>" + title + "</title>" + get_print_styles() + "</head><body>"
		+ print_button + hint + body_html + auto_print_script + "</body></html>"
	);
}

function get_print_styles() {
	return "<style>"
		+ "@page { size: A4 portrait; margin: 12mm 15mm; }"
		+ "* { box-sizing: border-box; margin: 0; padding: 0; background: transparent !important; color: #000 !important; font-family: Arial, Helvetica, sans-serif !important; font-size: 8.5pt; }"
		+ "body { background: #fff !important; }"
		+ ".sheet { width: 100%; position: relative; page-break-after: always; min-height: 250mm; padding-bottom: 12mm; margin-top: -10px; }"
		+ ".sheet:last-child { page-break-after: auto; }"
		
		/* Minimal Header Rule replacing Letterhead */
		+ ".doc-header-table { width: 100%; border-collapse: collapse; border-bottom: 1px solid #000; padding-bottom: 4px; margin-bottom: 20px; font-size: 7.5pt; }"
		+ ".doc-header-table td { padding-bottom: 4px; }"

		/* Title Formatting */
		+ ".doc-title { text-align: center; margin: 0 0 20px 0; }"
		+ ".doc-title h3 { font-size: 10pt; font-weight: bold; text-transform: uppercase; letter-spacing: 0.5px; }"
		+ ".doc-title .sub { font-size: 8.5pt; text-transform: uppercase; letter-spacing: 1px; margin-top: 3px; }"
		
		/* Clean Section Labels */
		+ ".section-label { font-size: 8.5pt; text-transform: uppercase; font-weight: bold; margin: 18px 0 6px 0; letter-spacing: 0.5px; margin-top: 35px;}"

		/* Clean Report Tables */
		+ ".report-table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }"
		+ ".report-table th { font-size: 7.5pt; text-transform: uppercase; font-weight: bold; padding: 6px 4px; border-top: 1.5px solid #000; border-bottom: 1px solid #000; text-align: left; }"
		+ ".report-table td { padding: 5px 4px; border: none; vertical-align: top; }"
		+ ".num { text-align: right; }"
		
		/* Subtotal Row */
        + ".subtotal-row td { border-top: 1px solid #000 !important; font-weight: bold; padding-top: 6px; padding-bottom: 6px; }"
        
		/* Signoff & Summary Layout */
		+ ".auth-page { margin-top: 10px; }"
		+ ".auth-intro { font-size: 9pt; line-height: 1.6; margin-bottom: 20px; text-align: justify; }"
		
		/* Clean Summary Table */
		+ ".summary-table { width: 100%; border-collapse: collapse; margin-bottom: 40px; }"
		+ ".summary-table td { padding-top: 8px; padding-bottom: 8px; border: none; font-size: 8.5pt; }"
		+ ".summary-table .grand-row td { font-weight: bold; font-size: 8.5pt; padding-top: 8px; padding-bottom: 8px; display: none;}"
		
		/* Signatures Block */
		+ ".sign-block { margin-top: 40px; }"
		+ ".sign-table { width: 100%; border-collapse: collapse; }"
		+ ".sign-table td { vertical-align: top; }"
		+ ".sign-line-title { font-size: 8pt; font-weight: bold; text-transform: uppercase; margin-bottom: 5px; }"
		+ ".sign-space { height: 50px; }"
		+ ".sign-border { border-top: 1px solid #000; margin-bottom: 5px; }"
		+ ".role { font-size: 8pt; line-height: 1.3; }"
		+ ".date-field { font-size: 8pt; margin-top: 10px; }"
		+ ".print-meta { font-size: 8pt; color: #000; text-align: right; margin-top: 10px; }"

		+ "@media print { .no-print { display: none !important; } }"
		+ "</style>";
}

function fmt_currency(val) {
	if (!val) return "0.00";
	return parseFloat(val).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

frappe.query_reports["Insurance Summary Check"] = {
    filters: [
        {
            fieldname: "member",
            label: __("Member No."),
            fieldtype: "Link",
            options: "Insurance Member",
            on_change: function() {
                frappe.query_report.refresh();
            }
        },
        {
            fieldname: "member_status",
            label: __("Member Status"),
            fieldtype: "Select",
            options: ["To Confirm", "Active", "Suspended", "Inactive"],
            default: "Active",
        },
        {
            fieldname: "insurance_scheme",
            label: __("Scheme"),
            fieldtype: "Link",
            options: "Support Scheme",
        },
        {
            fieldname: "category",
            label: __("Cover"),
            fieldtype: "Link",
            options: "Covers and Benefits",
        },
        {
            fieldname: "insurance_period",
            label: __("Insurance Period"),
            fieldtype: "Link",
            options: "Insurance Period",
        },
        {
            fieldname: "only_negative",
            label: __("Only Negative Balances"),
            fieldtype: "Check",
        },
        {
            fieldname: "only_negative_act",
            label: __("Only Negative Actual Balances"),
            fieldtype: "Check",
        },
        //{
        //    fieldname: "only_fraud",
        //    label: __("Only Fraud"),
        //    fieldtype: "Check",
        //},
    ],

    formatter(value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);

        if (!data) return value;

        // ---- CHANGE COLORS HERE ----
        const NEGATIVE = { text: "#b42318", bg: "#fee4e2" };   // minus balance cells

        const STATUS_COLORS = {
            "Fraud":                   { text: "#ffffff", bg: "#7a0c0c" },  // dark red, white text
            "Over limit with pending": { text: "#b42318", bg: "#fee4e2" },  // red
            "Limit reached":           { text: "#b54708", bg: "#fef0c7" },  // amber
            "Not used":                { text: "#667085", bg: "#f2f4f7" },  // grey
            "Within limit":            { text: "#067647", bg: "#dcfae6" },  // green
        };
        // -----------------------------

        const pill = (val, c) => `<span style="display:block; color:${c.text};
            background:${c.bg}; font-weight:600; padding:2px 6px;
            border-radius:4px;">${val}</span>`;

        if (column.fieldname === "balance" && flt(data.balance) < 0) {
            value = pill(value, NEGATIVE);
        }

        if (column.fieldname === "balance_without_pending" && flt(data.balance_without_pending) < 0) {
            value = pill(value, NEGATIVE);
        }

        if (column.fieldname === "status" && STATUS_COLORS[data.status]) {
            value = pill(value, STATUS_COLORS[data.status]);
        }

        return value;
    },

    get_chart_data: function(columns, data) {
        const member_filter = frappe.query_report.get_filter_value('member');

        // Hide chart completely if no Member No. is selected or no data exists
        if (!member_filter || !data || !data.length) {
            return null;
        }

        return {
            data: {
                labels: data.map(row => row.cover || row.category || "Cover"),
                datasets: [
                    {
                        name: "Balance",
                        // Round values to 2 decimal places to eliminate floating point accuracy bugs
                        values: data.map(row => flt(flt(row.balance).toFixed(2)))
                    },
                    {
                        name: "Balance Without Pending",
                        values: data.map(row => flt(flt(row.balance_without_pending).toFixed(2)))
                    }
                ]
            },
            type: "bar",
            height: 300,
            colors: ["#ad0909", "#171616"],
            // Formatter for chart tooltips (2 decimal places + thousands separator)
            tooltipOptions: {
                formatTooltipY: value => format_number(value, null, 2)
            },
            axisOptions: {
                shortenYAxisNumbers: 0
            }
        };
    },

    after_datatable_render: function(datatable) {
        const member_filter = frappe.query_report.get_filter_value('member');

        if (!member_filter) {
            if (frappe.query_report.chart_wrapper) {
                frappe.query_report.chart_wrapper.hide();
            }
            return;
        }

        if (frappe.query_report.chart_wrapper) {
            frappe.query_report.chart_wrapper.show();
        }

        // Highlight y=0 line in blue
        setTimeout(() => {
            const chartContainer = document.querySelector('.chart-container, .report-chart');
            if (!chartContainer) return;

            const ticks = chartContainer.querySelectorAll('svg .y.axis .tick, svg .y-axis .tick');
            ticks.forEach(tick => {
                const text = tick.querySelector('text');
                const line = tick.querySelector('line');
                if (text && line && text.textContent.trim() === '0') {
                    line.setAttribute('style', 'stroke: #0000ff !important; stroke-width: 3px !important; stroke-opacity: 1 !important;');
                }
            });
        }, 200);
    }
};
